UPDATE qna
SET
title = #{title},
question = #{question}
WHERE qna_idx = #{qna_idx}

mapper.select:

SELECT * FROM (
  SELECT ROWNUM rnum, a.* FROM (
    SELECT
      q.qna_idx    AS "qna_idx",
      q.title      AS "title",
      q.qna_type   AS "qna_type",
      q.question   AS "question",
      q.created_at AS "created_at"
    FROM qna q
    WHERE q.qna_type = #{type}
    ORDER BY q.qna_idx DESC
  ) a
  WHERE ROWNUM <= #{endRow}
)
WHERE rnum >= #{startRow}

SELECT COUNT(*)
FROM qna 
WHERE qna_type=#{type}
